import{_ as o,o as a,c as i,a2 as e}from"./chunks/framework.CHeM0PsO.js";const f=JSON.parse('{"title":"Gemini / Veo 广告片踩坑速查地图","description":"","frontmatter":{},"headers":[],"relativePath":"tools/gemini-pitfalls.md","filePath":"tools/gemini-pitfalls.md","lastUpdated":1787714366000}'),r={name:"tools/gemini-pitfalls.md"};function d(l,t,n,s,g,h){return a(),i("div",null,[...t[0]||(t[0]=[e('<h1 id="gemini-veo-广告片踩坑速查地图" tabindex="-1">Gemini / Veo 广告片踩坑速查地图 <a class="header-anchor" href="#gemini-veo-广告片踩坑速查地图" aria-label="Permalink to &quot;Gemini / Veo 广告片踩坑速查地图&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">来源与说明</p><ul><li>来源：Web 检索整理的行业社区反馈（Reddit / X / 中文社区）+ 本站 Gemini 专题系列交叉</li><li>时间：2026-08-16</li><li>说明：本文是「坑的分类地图」，只回答「会在哪里翻车、翻车了去哪篇拿解法」，<strong>不记录具体参数</strong>（时长上限、分辨率上限、订阅档位等随时变化，请以官网为准）。各坑的详细解法已拆成知识库内的单点专题，本文只做索引；社区反馈未经 Google 官方逐一核实。</li></ul></div><p>这篇不教你写 Prompt，而是先回答一个问题：<strong>用 Gemini / Veo 做广告片，会在哪些地方翻车？</strong> 遇到具体坑，点内链进对应专题拿可直接复制的 Prompt。</p><h2 id="一张速查表" tabindex="-1">一张速查表 <a class="header-anchor" href="#一张速查表" aria-label="Permalink to &quot;一张速查表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>翻车表现</th><th>属于哪类坑</th><th>解法入口</th></tr></thead><tbody><tr><td>片长不对、被拖到默认时长</td><td>时长</td><td><a href="/tools/gemini-video-duration">控制视频时长</a></td></tr><tr><td>同一个主角换镜头就变样、服装发型漂移</td><td>一致性</td><td><a href="/tools/gemini-shot-consistency">跨镜头一致性</a></td></tr><tr><td>包装上的字 / Logo 乱码、变形</td><td>文字渲染</td><td><a href="/tools/gemini-packaging-logo">包装文字不崩</a></td></tr><tr><td>手指数量不对、进食 / 口腔崩坏</td><td>肢体细节</td><td><a href="/tools/gemini-hands-eating">手部与进食特写</a></td></tr><tr><td>材质假、调味粉变贴图、油脂没折射</td><td>材质</td><td><a href="/tools/gemini-food-material">食品材质不漂移</a></td></tr><tr><td>运镜像「无重力幽灵」乱窜</td><td>运镜</td><td><a href="/tools/gemini-camera-movement">机位与运镜</a></td></tr><tr><td>用了某个运镜词必崩</td><td>运镜</td><td><a href="/tools/gemini-camera-failsafe">运镜翻车词</a></td></tr><tr><td>升格 / 延时 / 停格拍不出来</td><td>时间效果</td><td><a href="/tools/gemini-time-effects">升格延时停格</a></td></tr><tr><td>「不要 XX」写了没用</td><td>负面约束</td><td><a href="/tools/gemini-negative-tokens">排除项写法</a></td></tr><tr><td>参考图把风格也锁死了</td><td>参考图</td><td><a href="/tools/gemini-reference-image">参考图去风格</a></td></tr><tr><td>首帧填不上、中间帧发糊</td><td>首尾帧</td><td><a href="/tools/gemini-first-last-frame">首帧与首尾帧</a></td></tr><tr><td>声音 / 口播对不上嘴型</td><td>音频</td><td><a href="/tools/gemini-sound-asmr">声音 / 旁白 / ASMR</a></td></tr><tr><td>出了废片，不知道从哪查起</td><td>诊断</td><td><a href="/tools/gemini-fail-diagnosis">失败诊断与去廉价感</a></td></tr></tbody></table><h2 id="一、三类生成质量坑-已被专题覆盖-这里只点题" tabindex="-1">一、三类生成质量坑（已被专题覆盖，这里只点题） <a class="header-anchor" href="#一、三类生成质量坑-已被专题覆盖-这里只点题" aria-label="Permalink to &quot;一、三类生成质量坑（已被专题覆盖，这里只点题）&quot;">​</a></h2><p>动手前记住三句话，细节去专题看：</p><ol><li><strong>时长是最大的错觉</strong>：很多人以为能一次出几十秒，实际单次生成很有限（主流多在 5~10 秒量级，以你当前套餐为准）。长片必须拆镜、分镜生成、后期拼。→ <a href="/tools/gemini-video-duration">控制视频时长</a></li><li><strong>角色一致性是广告片的头号盲点</strong>：同一主角贯穿多镜，纯文本反复生必漂。可靠做法是「资产解耦定型 → 单镜头静态关键帧 → 图生视频」，而不是用同一张参考图死锁所有分镜首帧。→ <a href="/tools/gemini-shot-consistency">跨镜头一致性</a></li><li><strong>品牌字、口号、Logo 别指望 AI 写对</strong>：尤其中文，生成里文字乱码是常态。正确姿势是「净版生成 + 后期平面跟踪贴标」。→ <a href="/tools/gemini-packaging-logo">包装文字不崩</a></li></ol><h2 id="二、平台与账号边界-专题未覆盖-本文新增" tabindex="-1">二、平台与账号边界（专题未覆盖，本文新增） <a class="header-anchor" href="#二、平台与账号边界-专题未覆盖-本文新增" aria-label="Permalink to &quot;二、平台与账号边界（专题未覆盖，本文新增）&quot;">​</a></h2><p>这类坑不在 Prompt 里，而在「能不能用、用完能不能商用」：</p><ul><li><strong>地区可用性</strong>：视频生成能力并非所有地区 / 账号类型都开放，企业版、教育版账号可能被锁功能。</li><li><strong>订阅额度</strong>：免费档与付费档可用额度差异大，超额需等下个周期，具体档位以官网为准。</li><li><strong>内容审核</strong>：真实人物（尤其名人 / 政治人物）、暴力血腥、色情、版权角色会被拒；连「模仿某风格」的描述都可能触发误判。</li><li><strong>SynthID 隐形水印</strong>：生成内容带不可见数字水印，肉眼看不出来，但可能影响某些平台的内容审核或 AI 检测判定。</li><li><strong>负面提示词支持偏弱</strong>：App 端对精细 negative prompt 的支持有限，与其写「不要 XX」，不如换措辞正面规避。→ <a href="/tools/gemini-negative-tokens">排除项写法</a></li></ul><blockquote><p>以上边界随时变动，动手前以官网和账号后台实际状态为准。</p></blockquote><h2 id="三、三条总是成立的工作方式" tabindex="-1">三、三条总是成立的工作方式 <a class="header-anchor" href="#三、三条总是成立的工作方式" aria-label="Permalink to &quot;三、三条总是成立的工作方式&quot;">​</a></h2><p>参数和档位会变，但这三件事在可预见的范围内不会变：</p><ol><li><strong>单镜短、分镜拆、后期拼</strong>。单次生成短是现状，不是缺陷；把它当成「每镜一个素材」而不是「一次出全片」。</li><li><strong>角色锁死走「先图后视频」</strong>。先出静态关键帧（图模型），再图生视频，能最大程度压住漂移。→ <a href="/tools/gemini-shot-consistency">跨镜头一致性</a> · <a href="/tools/gemini-first-last-frame">首帧与首尾帧</a></li><li><strong>品牌元素交给后期</strong>。AI 负责画面和质感，Logo、口号、排版文字一律后期套件，永不指望生成端写对。</li></ol><hr><h2 id="附-和「失败诊断」的分工" tabindex="-1">附：和「失败诊断」的分工 <a class="header-anchor" href="#附-和「失败诊断」的分工" aria-label="Permalink to &quot;附：和「失败诊断」的分工&quot;">​</a></h2><ul><li>这篇（踩坑速查地图）：<strong>动手前</strong>先知道坑在哪，按「翻车表现」反查解法。</li><li><a href="/tools/gemini-fail-diagnosis">失败诊断与去廉价感</a>：<strong>出片后</strong>片子废了，按「时长 → 运镜 → 材质 → 色调」的诊断顺序一步步收敛。</li></ul><p>一个是地图，一个是排障顺序，配合着用。</p>',19)])])}const c=o(r,[["render",d]]);export{f as __pageData,c as default};
